import{c as d,Q as r,j as a,m as s}from"./chunks/framework.CWCyN0M6.js";const m=JSON.parse('{"title":"第4章 信息系统规划","description":"","frontmatter":{},"headers":[],"relativePath":"02-方法篇/ch04-信息系统规划.md","filePath":"02-方法篇/ch04-信息系统规划.md","lastUpdated":1779705625000}'),o={name:"02-方法篇/ch04-信息系统规划.md"};function n(e,t,l,i,h,c){return r(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="第4章-信息系统规划" tabindex="-1">第4章 信息系统规划 <a class="header-anchor" href="#第4章-信息系统规划" aria-label="Permalink to &quot;第4章 信息系统规划&quot;">​</a></h1><blockquote><p><strong>教材页码</strong>：105-137（33页） | <strong>考纲位置</strong>：知识点4（三科共考核心区起点） <strong>首考数据</strong>：综合约1-2题，论文可能直接出题</p></blockquote><hr><h2 id="📊-一、章节速览图谱" tabindex="-1">📊 一、章节速览图谱 <a class="header-anchor" href="#📊-一、章节速览图谱" aria-label="Permalink to &quot;📊 一、章节速览图谱&quot;">​</a></h2><div class="mm-ch4"><div class="mm-root">📊 第4章 信息系统规划</div><details class="mm-sec mm-s41" open><summary>4.1 概述 <span class="mm-tag">六大原则</span></summary><div class="mm-body"><div class="mm-pills"><span class="mm-pill">战略</span><span class="mm-pill">整体</span><span class="mm-pill">先进</span><span class="mm-pill">指导</span><span class="mm-pill">柔性</span><span class="mm-pill">遵从</span></div></div></details><details class="mm-sec mm-s42" open><summary>4.2 主要内容 <span class="mm-tag">七大体系</span></summary><div class="mm-body"><div class="mm-cards"><div class="mm-card"><div class="mm-card-title">4.2.1 发展战略</div><div class="mm-card-desc">目标树 / 5级成熟度 / 发展路径</div></div><div class="mm-card"><div class="mm-card-title">4.2.2 系统框架</div><div class="mm-card-desc">应用功能 → 平台能力 → 互联网主线</div></div><div class="mm-card"><div class="mm-card-title">4.2.3 组织体系</div><div class="mm-card-desc">中小型 / 集中式 / 分权式 / 平衡矩阵</div></div><div class="mm-card"><div class="mm-card-title">4.2.4 技术体系</div><div class="mm-card-desc">6原则 / 技术蓝图两种图</div></div><div class="mm-card"><div class="mm-card-title">4.2.5 任务体系</div><div class="mm-card-desc">拆解 → 目标 → 组织 → 策略 → 计划 → 监控</div></div><div class="mm-card"><div class="mm-card-title">4.2.6 资源体系</div><div class="mm-card-desc">识别评估 → 关系控制 → 分配调度 → 风险优化</div></div><div class="mm-card"><div class="mm-card-title">4.2.7 保障体系</div><div class="mm-card-desc">组织 / 人员 / 技术 / 资源 / 数据 / 安全</div></div></div></div></details><details class="mm-sec mm-s43" open><summary>4.3 工作要点 <span class="mm-tag">五步法</span></summary><div class="mm-body"><div class="mm-steps"><span class="mm-step">📥 需求挖掘</span><span class="mm-step-arrow">→</span><span class="mm-step">🔍 场景分析</span><span class="mm-step-arrow">→</span><span class="mm-step">📊 诊断评估</span><span class="mm-step-arrow">→</span><span class="mm-step">📐 整体专项规划</span><span class="mm-step-arrow">→</span><span class="mm-step">🔄 持续改进</span></div></div></details><details class="mm-sec mm-s44" open><summary>4.4 五种方法 <span class="mm-tag">⭐高频考点</span></summary><div class="mm-body mm44"><div class="mm-cards"><div class="mm-card"><div class="mm-card-title">SST 战略目标集转移</div><div class="mm-author">King · 1978</div></div><div class="mm-card"><div class="mm-card-title">BSP 企业系统规划</div><div class="mm-author">IBM · 1970s</div></div><div class="mm-card"><div class="mm-card-title">CSF 关键成功因素</div><div class="mm-author">Zani/Rockart · 1970</div></div><div class="mm-card"><div class="mm-card-title">VCA 价值链分析</div><div class="mm-author">Porter · 1985</div></div><div class="mm-card"><div class="mm-card-title">Zachman 框架</div><div class="mm-author">Zachman · 1987</div></div></div></div></details></div><hr><h2 id="📖-二、逐节知识精炼" tabindex="-1">📖 二、逐节知识精炼 <a class="header-anchor" href="#📖-二、逐节知识精炼" aria-label="Permalink to &quot;📖 二、逐节知识精炼&quot;">​</a></h2><h3 id="_4-1-概述" tabindex="-1">4.1 概述 <a class="header-anchor" href="#_4-1-概述" aria-label="Permalink to &quot;4.1 概述&quot;">​</a></h3><p><strong>信息系统规划的定义</strong>：组织决策层任主要负责人，管理层为工作主体，使用自顶向下分解 / 自底向上聚合，确定信息系统的整体发展战略、总体框架、演进路径和资源分配策略。</p><p><strong>信息系统规划的六大原则</strong>（记忆口诀：战整先指柔遵）：</p><table tabindex="0"><thead><tr><th>#</th><th>原则</th><th>核心要点</th></tr></thead><tbody><tr><td>1</td><td><strong>战略性</strong></td><td>从战略视角定义目标价值，驱动引领组织建设，与组织战略保持一致</td></tr><tr><td>2</td><td><strong>整体性</strong></td><td>四个方面——业务赋能、系统框架、建设实施、集成融合</td></tr><tr><td>3</td><td><strong>先进性</strong></td><td>①考虑技术发展趋势选择适当路线；②融合内外部最佳实践</td></tr><tr><td>4</td><td><strong>指导性</strong></td><td>从业务需求、技术方案、实施管理、成本控制、范围界定、风险预防等方面给出框架性要求</td></tr><tr><td>5</td><td><strong>柔性</strong></td><td>满足对内外部环境变化的适应性，明确监测调整优化的基本原则</td></tr><tr><td>6</td><td><strong>遵从性</strong></td><td>①法律法规；②标准规范；③组织战略与数字能力发展需求</td></tr></tbody></table><hr><h3 id="_4-2-信息系统规划主要内容-7大体系" tabindex="-1">4.2 信息系统规划主要内容（7大体系） <a class="header-anchor" href="#_4-2-信息系统规划主要内容-7大体系" aria-label="Permalink to &quot;4.2 信息系统规划主要内容（7大体系）&quot;">​</a></h3><h4 id="_4-2-1-信息系统发展战略" tabindex="-1">4.2.1 信息系统发展战略 <a class="header-anchor" href="#_4-2-1-信息系统发展战略" aria-label="Permalink to &quot;4.2.1 信息系统发展战略&quot;">​</a></h4><p><strong>信息系统战略</strong> = 目标 + 方法 + 策略 + 措施的总称。</p><p><strong>（一）发展战略与目标</strong></p><table tabindex="0"><thead><tr><th>要素</th><th>内容</th></tr></thead><tbody><tr><td><strong>基本趋势</strong></td><td>信息技术革命、互联网创新、数字化转型与智能化发展等外部信息环境</td></tr><tr><td><strong>指导思想</strong></td><td>覆盖国家战略、行业领域要求、上级主管部门与主要负责人思想</td></tr><tr><td><strong>战略目标</strong></td><td>以时间为轴线、以阶段为区隔，定性与定量结合表达</td></tr><tr><td><strong>基本方针</strong></td><td>高度概括、动宾结构排比、方便记忆传播</td></tr></tbody></table><p><strong>（二）发展路径与阶段</strong></p><p><strong>四种路径原则</strong>：业务一致 → 能力主线 → 基础优先 → 稳态先行</p><p><strong>五个发展阶段（成熟度5级）</strong>：</p><table tabindex="0"><thead><tr><th>等级</th><th>核心主旨</th><th>关键词</th></tr></thead><tbody><tr><td>一级</td><td><strong>打基础</strong></td><td>业务规范化、数字化意识、局部系统建设</td></tr><tr><td>二级</td><td><strong>提效率</strong></td><td>团队/部门职能、工作效率、全面推进系统建设</td></tr><tr><td>三级</td><td><strong>做协同</strong></td><td>数据共治共享、数据流优化业务流、多元协同</td></tr><tr><td>四级</td><td><strong>强决策</strong></td><td>数据模型开发利用、决策效率效能、治理模式变革</td></tr><tr><td>五级</td><td><strong>构生态</strong></td><td>跨组织融合、云和互联网模式、广域协同</td></tr></tbody></table><blockquote><p>⚡ <strong>首考关联</strong>：2025年11月综合真题考了「敏捷组织 + GBT43439」，这是成熟度相关国标，与本节直接相关。</p></blockquote><h4 id="_4-2-2-主要系统框架" tabindex="-1">4.2.2 主要系统框架 <a class="header-anchor" href="#_4-2-2-主要系统框架" aria-label="Permalink to &quot;4.2.2 主要系统框架&quot;">​</a></h4><p><strong>总体框架</strong>：「感、传、智、用、安」五层 + 服务总线 + 安全保障体系</p><p><strong>三种框架演进路径</strong>：</p><table tabindex="0"><thead><tr><th>框架类型</th><th>适用阶段</th><th>核心理念</th><th>局限</th></tr></thead><tbody><tr><td><strong>以应用功能为主线</strong></td><td>中小型 / 信息化初期</td><td>&quot;拿来主义&quot;、成套软件、按部门职能建设</td><td>系统间集成困难</td></tr><tr><td><strong>以平台能力为主线</strong></td><td>规模扩大 / 个性化需求</td><td>平层化建设、数据共享、双态IT（稳态+敏态）</td><td>无法包容生态伙伴差异</td></tr><tr><td><strong>以互联网为主线</strong></td><td>产业链/生态链阶段</td><td>App化微服务、能力封装、成熟度差异适配</td><td>技术复杂度高</td></tr></tbody></table><p><strong>四种分系统划分原则</strong>：技术一致性、工程一致性、职能一致性、数据一致性</p><h4 id="_4-2-3-组织体系优化" tabindex="-1">4.2.3 组织体系优化 <a class="header-anchor" href="#_4-2-3-组织体系优化" aria-label="Permalink to &quot;4.2.3 组织体系优化&quot;">​</a></h4><table tabindex="0"><thead><tr><th>模式</th><th>适用对象</th><th>特点</th></tr></thead><tbody><tr><td><strong>中小型</strong></td><td>中小企业</td><td>信息化管理委员会 + 信息化团队</td></tr><tr><td><strong>集中式</strong></td><td>大型单位</td><td>专业信息部门、最高管理者第一责任人、专职架构/质量/测试人员</td></tr><tr><td><strong>分权式</strong></td><td>业务单元差异大</td><td>各业务单元自行建设、设统筹负责人或虚拟团队</td></tr><tr><td><strong>平衡矩阵式</strong></td><td>成熟度较高</td><td>稳态集中建设 + 敏态分权管理，业务侧重数据开发</td></tr></tbody></table><h4 id="_4-2-4-技术体系定义" tabindex="-1">4.2.4 技术体系定义 <a class="header-anchor" href="#_4-2-4-技术体系定义" aria-label="Permalink to &quot;4.2.4 技术体系定义&quot;">​</a></h4><p><strong>六大定义原则</strong>（记忆口诀：可用安全靠灵扩驾）：</p><table tabindex="0"><thead><tr><th>原则</th><th>关键内容</th></tr></thead><tbody><tr><td><strong>可用性</strong></td><td>不是二元（行/不行），是可用程度的问题，需多维度排序</td></tr><tr><td><strong>安全性</strong></td><td>安全漏洞认知 + 故障影响最小 + 与信息安全管理体系匹配</td></tr><tr><td><strong>可靠性</strong></td><td>三方面考察：成熟性、技术整体性、技术风险性</td></tr><tr><td><strong>灵活性</strong></td><td>技术组件化 + 技术组合架构，少量变化满足新需求</td></tr><tr><td><strong>可扩展性</strong></td><td>韧性拓展，适应更多用户/业务/数据/交互</td></tr><tr><td><strong>可驾驭性</strong></td><td>直接/间接/混合方式，确保充分掌控关键技术</td></tr></tbody></table><p><strong>技术蓝图两种绘制方法</strong>：逻辑结构图 + 技术应用图</p><h4 id="_4-2-5-任务体系部署" tabindex="-1">4.2.5 任务体系部署 <a class="header-anchor" href="#_4-2-5-任务体系部署" aria-label="Permalink to &quot;4.2.5 任务体系部署&quot;">​</a></h4><p><strong>六步过程</strong>：任务拆解 → 明确目标 → 匹配组织 → 制定策略 → 定义计划 → 监控实施</p><p><strong>三层目标原则</strong>：<strong>S</strong>pecific 具体 + <strong>M</strong>easurable 可测量 + <strong>A</strong>chievable 可实现</p><h4 id="_4-2-6-资源体系调度" tabindex="-1">4.2.6 资源体系调度 <a class="header-anchor" href="#_4-2-6-资源体系调度" aria-label="Permalink to &quot;4.2.6 资源体系调度&quot;">​</a></h4><p><strong>四步</strong>：资源识别与评估 → 资源关系与控制 → 资源分配与调度 → 资源风险与优化</p><p><strong>资源识别</strong>：可基于能力要素（人员/技术/流程/软硬件），也可基于「人机料法环测」六要素。</p><h4 id="_4-2-7-保障体系设定" tabindex="-1">4.2.7 保障体系设定 <a class="header-anchor" href="#_4-2-7-保障体系设定" aria-label="Permalink to &quot;4.2.7 保障体系设定&quot;">​</a></h4><table tabindex="0"><thead><tr><th>保障类型</th><th>核心重点</th></tr></thead><tbody><tr><td><strong>组织</strong></td><td>决策层承诺、组织变革支持、思想认识一致性</td></tr><tr><td><strong>人员</strong></td><td>全员数字能力培养、变革接受预期、碎片化时间利用</td></tr><tr><td><strong>技术</strong></td><td>储备预研、微创新鼓励、标准化驱动</td></tr><tr><td><strong>资源</strong></td><td>软实力建设、云服务获取硬资源、优先级提升</td></tr><tr><td><strong>数据</strong></td><td>数据治理能力、数据质量、数据标准化、数据开发</td></tr><tr><td><strong>安全</strong></td><td>安全意识、安全知识技能、安全管理体系</td></tr></tbody></table><hr><h3 id="_4-3-信息系统规划工作要点-五步法" tabindex="-1">4.3 信息系统规划工作要点（五步法） <a class="header-anchor" href="#_4-3-信息系统规划工作要点-五步法" aria-label="Permalink to &quot;4.3 信息系统规划工作要点（五步法）&quot;">​</a></h3><blockquote><p>⚠️ <strong>重要</strong>：5个工作要点构成一个完整闭环，是案例题的高频考点。</p></blockquote><p><strong>五步递进</strong>：内外部需求挖掘 → 场景化模型分析 → 深度诊断与评估 → 整体与专项规划 → 持续改进</p><h4 id="_4-3-1-内外部需求挖掘" tabindex="-1">4.3.1 内外部需求挖掘 <a class="header-anchor" href="#_4-3-1-内外部需求挖掘" aria-label="Permalink to &quot;4.3.1 内外部需求挖掘&quot;">​</a></h4><p><strong>内部需求挖掘 — 五项任务</strong>：理解组织战略 / 熟悉业务流程 / 收集用户需求 / 评估现有系统 / 感知数字环境</p><p><strong>五项注意事项</strong>：以原始信息获取为主 / 避免直接给出解决方案 / 及时开展引导性培训 / 谨慎信息交叉传递 / 关注隐性需求的推演</p><p><strong>外部需求挖掘 — 六项任务</strong>：国家战略导入 / 行业趋势分析 / 技术趋势研究 / 竞争环境分析 / 客户期望调研 / 标准与规范引用</p><p><strong>整合分析关注的9项内容</strong>：主要矛盾、需求优先级、关键干系人需求、外部要求、创新环境、数字化水平、治理与文化模式、重大风险、推进策略</p><h4 id="_4-3-2-场景化模型分析" tabindex="-1">4.3.2 场景化模型分析 <a class="header-anchor" href="#_4-3-2-场景化模型分析" aria-label="Permalink to &quot;4.3.2 场景化模型分析&quot;">​</a></h4><p><strong>八维度分析模型</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>内容</th></tr></thead><tbody><tr><td>场景定义</td><td>目标、范围、业务背景、利益相关者</td></tr><tr><td>角色分析</td><td>职责、需求、行为、作用与影响</td></tr><tr><td>业务分析</td><td>业务模式、流程、需求、发展</td></tr><tr><td>数据分析</td><td>数据流、数据来源/类型/结构、开发利用价值</td></tr><tr><td>技术分析</td><td>管理/工艺/决策/信息技术现状与发展</td></tr><tr><td>组织分析</td><td>组织文化、人员技能、组织流程</td></tr><tr><td>风险分析</td><td>技术/安全/管理风险与应对策略</td></tr><tr><td>政策与法律分析</td><td>合规性分析</td></tr></tbody></table><p><strong>三阶段应用</strong>：规划前（识别需求）→ 规划中（评估方案可行性与风险）→ 规划后（监控评估效果）</p><h4 id="_4-3-3-深度诊断与评估" tabindex="-1">4.3.3 深度诊断与评估 <a class="header-anchor" href="#_4-3-3-深度诊断与评估" aria-label="Permalink to &quot;4.3.3 深度诊断与评估&quot;">​</a></h4><p><strong>核心工具</strong>：成熟度模型（5级）</p><table tabindex="0"><thead><tr><th>等级</th><th>核心内涵</th></tr></thead><tbody><tr><td>一级</td><td>确立主要工作 + 基本策划 + 规范化建设</td></tr><tr><td>二级</td><td>管理精细化流程化 + 解决运行效率</td></tr><tr><td>三级</td><td>协同一体化 + 数据流替代业务流程 + 知识沉淀</td></tr><tr><td>四级</td><td>敏捷能力建设 + 数据模型预测决策 + 治理改革</td></tr><tr><td>五级</td><td>生态一体化 + 自组织模式 + 应对未知风险</td></tr></tbody></table><p><strong>相关国标</strong>：GB/T 43439（数字转型成熟度）、GB/T 39116（智能制造成熟度）</p><p><strong>诊断评估实施三步</strong>：</p><ol><li><strong>计划与打分</strong>：0分/0.5分/0.8分/1分四级打分，由低到高逐级</li><li><strong>权重与计算</strong>：参考标准或自动设定</li><li><strong>记录与确认</strong>：形成底稿，标注不满足项，获得干系人确认</li></ol><p><strong>木桶原理</strong>：组织整体能力水平 = 最短板的能力水平状态</p><h4 id="_4-3-4-整体与专项规划" tabindex="-1">4.3.4 整体与专项规划 <a class="header-anchor" href="#_4-3-4-整体与专项规划" aria-label="Permalink to &quot;4.3.4 整体与专项规划&quot;">​</a></h4><p><strong>需求整合三维度</strong>：业务领域维 / 能力建设维 / 技术发展维</p><p><strong>整体规划</strong>三要点：与战略一致性、协同一体化、资源优化</p><p><strong>专项规划</strong>四要点：明确主体、领域系统性、技术路线强化、细致时间轴</p><p><strong>一致性检查</strong>四方面：规划-需求对应、内容协调、科学可行性、干系人理解一致</p><h4 id="_4-3-5-持续改进" tabindex="-1">4.3.5 持续改进 <a class="header-anchor" href="#_4-3-5-持续改进" aria-label="Permalink to &quot;4.3.5 持续改进&quot;">​</a></h4><p><strong>五个关注点</strong>：战略跟踪 → 技术感知 → 数据安全 → 用户体验 → 监测评估</p><hr><h3 id="_4-4-信息系统规划常用方法-⭐高频考点" tabindex="-1">4.4 信息系统规划常用方法（⭐高频考点） <a class="header-anchor" href="#_4-4-信息系统规划常用方法-⭐高频考点" aria-label="Permalink to &quot;4.4 信息系统规划常用方法（⭐高频考点）&quot;">​</a></h3><blockquote><p>🔥 <strong>五星重要</strong>：五种方法的名字、提出者、年份、核心思想是综合选择题的绝对高频考点。</p></blockquote><h4 id="对比总表-先记这个" tabindex="-1">对比总表（先记这个） <a class="header-anchor" href="#对比总表-先记这个" aria-label="Permalink to &quot;对比总表（先记这个）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>方法</th><th>提出者</th><th>年份</th><th>核心思想</th><th>一句话</th></tr></thead><tbody><tr><td><strong>SST</strong></td><td>William King</td><td>1978</td><td>组织战略集→信息系统战略集的转换</td><td>「翻译」组织战略为系统战略</td></tr><tr><td><strong>BSP</strong></td><td>IBM公司</td><td>1970s</td><td>自顶向下分析需求，自底向上设计结构</td><td>「调查分析」企业信息需求定方案</td></tr><tr><td><strong>CSF</strong></td><td>Zani / Rockart</td><td>1970/1980</td><td>少数关键成功因素决定信息需求</td><td>「抓住」主要矛盾定信息需求</td></tr><tr><td><strong>VCA</strong></td><td>Michael Porter</td><td>1985</td><td>价值链上识别战略环节优先部署IT</td><td>「找到」增值环节优先上IT</td></tr><tr><td><strong>Zachman</strong></td><td>John Zachman</td><td>1987</td><td>6W×6层 = 36格的企业架构分类</td><td>「网格化」描述企业信息</td></tr></tbody></table><h4 id="_4-4-1-sst-战略目标集转移法" tabindex="-1">4.4.1 SST 战略目标集转移法 <a class="header-anchor" href="#_4-4-1-sst-战略目标集转移法" aria-label="Permalink to &quot;4.4.1 SST 战略目标集转移法&quot;">​</a></h4><ul><li><strong>核心</strong>：把组织战略集（使命/目标/战略/属性）→ 转换成 → 信息系统战略集（系统目标/约束/建设战略）</li><li><strong>三步法</strong>：①画出利益相关方结构 → ②确定利益相关方要求 → ③定义组织对每个利益相关方的任务和战略</li></ul><h4 id="_4-4-2-bsp-企业信息系统规划法" tabindex="-1">4.4.2 BSP 企业信息系统规划法 <a class="header-anchor" href="#_4-4-2-bsp-企业信息系统规划法" aria-label="Permalink to &quot;4.4.2 BSP 企业信息系统规划法&quot;">​</a></h4><ul><li><p><strong>四个基本步骤</strong>：</p><ol><li><strong>定义管理目标</strong> — 采访各级管理层，绘制目标树</li><li><strong>定义管理功能</strong> — 基于资源的生命周期识别（产生/获得/服务/归宿）</li><li><strong>定义数据类</strong> — 实体法 + 功能法，归纳10~20个数据类</li><li><strong>定义信息结构</strong> — 功能/数据类矩阵→C-U矩阵→聚类分组→子系统划分</li></ol></li><li><p><strong>核心理念</strong>：管理功能应独立于组织机构（组织变动不影响系统设计）</p></li></ul><h4 id="_4-4-3-csf-关键成功因素法" tabindex="-1">4.4.3 CSF 关键成功因素法 <a class="header-anchor" href="#_4-4-3-csf-关键成功因素法" aria-label="Permalink to &quot;4.4.3 CSF 关键成功因素法&quot;">​</a></h4><ul><li><strong>四个主要来源</strong>：①个别产业结构 ②竞争策略与产业地位 ③环境因素 ④暂时因素</li><li><strong>四类CSF</strong>：内部型 / 外部型 / 监控型 / 建立型</li><li><strong>四步实施</strong>：①确定战略目标 → ②识别所有成功因素 → ③确定关键成功因素 → ④识别绩效指标</li></ul><h4 id="_4-4-4-vca-价值链分析法" tabindex="-1">4.4.4 VCA 价值链分析法 <a class="header-anchor" href="#_4-4-4-vca-价值链分析法" aria-label="Permalink to &quot;4.4.4 VCA 价值链分析法&quot;">​</a></h4><ul><li><strong>四个基本观点</strong>：价值核心 / 基本+支持活动 / 相互依存 / 竞争优势来自优化</li><li><strong>四步应用</strong>：识别价值链 → 确定关键价值增加环节 → 确定关键价值减少环节 → 明确IT支持</li></ul><h4 id="_4-4-5-zachman框架" tabindex="-1">4.4.5 Zachman框架 <a class="header-anchor" href="#_4-4-5-zachman框架" aria-label="Permalink to &quot;4.4.5 Zachman框架&quot;">​</a></h4><ul><li><strong>结构</strong>：6行（纵向）× 6列（横向）= 36格</li><li><strong>横向6W</strong>：What（数据）/ How（功能）/ Where（网络）/ Who（人员）/ When（时间）/ Why（动机）</li><li><strong>纵向6层</strong>：范围模型 → 企业模型 → 系统模型 → 技术模型 → 详细模型 → 功能模型</li></ul><hr><h2 id="🎯-三、综合知识考点速查" tabindex="-1">🎯 三、综合知识考点速查 <a class="header-anchor" href="#🎯-三、综合知识考点速查" aria-label="Permalink to &quot;🎯 三、综合知识考点速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>考点</th><th>可能出题方式</th><th>记忆要点</th></tr></thead><tbody><tr><td>六大规划原则</td><td>挑出不属于/属于的</td><td>战整先指柔遵</td></tr><tr><td>五级成熟度</td><td>对应关系判断</td><td>一基二效三协四决五生态</td></tr><tr><td>三种框架演进</td><td>场景匹配型</td><td>小→应用、中→平台、大→互联网</td></tr><tr><td>技术体系六原则</td><td>挑出不属于的</td><td>可用安全靠灵扩驾</td></tr><tr><td>五步工作要点</td><td>顺序题</td><td>需求→场景→诊断→规划→改进</td></tr><tr><td>SST/BSP/CSF/VCA/Zachman</td><td>方法-提出者-年份-特点匹配</td><td>见对比总表</td></tr><tr><td>BSP四步骤</td><td>顺序题</td><td>目标→功能→数据类→信息结构</td></tr><tr><td>CSF四来源</td><td>挑出不属于的</td><td>产业结构/竞争策略/环境/暂时因素</td></tr><tr><td>Zachman 6W</td><td>对应关系</td><td>What=数据/How=功能/Where=网络/Who=人员/When=时间/Why=动机</td></tr></tbody></table><hr><h2 id="📝-四、案例分析答题模板" tabindex="-1">📝 四、案例分析答题模板 <a class="header-anchor" href="#📝-四、案例分析答题模板" aria-label="Permalink to &quot;📝 四、案例分析答题模板&quot;">​</a></h2><p><strong>STAR-L 答题框架</strong>：</p><ul><li>S - 场景重现 → 定位到4.3五步法哪个环节出了问题</li><li>T - 应达目标 → 引用4.1六大原则或4.2相关体系要求</li><li>A - 应采取行动 → 从4.3工作要点选择对应步骤</li><li>R - 预期结果 → 从4.2各体系输出标准描述</li><li>L - 经验教训 → 引用4.3.5持续改进五个关注点</li></ul><table tabindex="0"><thead><tr><th>问题类型</th><th>对应章节</th><th>答题思路</th></tr></thead><tbody><tr><td>需求分析不充分</td><td>4.3.1</td><td>列出内外部需求挖掘的任务和注意事项</td></tr><tr><td>系统框架选择错误</td><td>4.2.2</td><td>描述三种框架的适用阶段</td></tr><tr><td>规划方法选择</td><td>4.4</td><td>对比5种方法的优缺点和适用场景</td></tr><tr><td>组织体系设置问题</td><td>4.2.3</td><td>分析应采用的模式</td></tr></tbody></table><hr><h2 id="✍️-五、论文写作框架" tabindex="-1">✍️ 五、论文写作框架 <a class="header-anchor" href="#✍️-五、论文写作框架" aria-label="Permalink to &quot;✍️ 五、论文写作框架&quot;">​</a></h2><h3 id="万能论文框架" tabindex="-1">万能论文框架 <a class="header-anchor" href="#万能论文框架" aria-label="Permalink to &quot;万能论文框架&quot;">​</a></h3><ul><li>【摘要】300字：项目背景 + 我的角色 + 本文重点 + 成果简述</li><li>【正文-背景】400字：组织基本情况、信息化现状、项目目标</li><li>【正文-方法】800字：规划方法选择理由 + 具体实施步骤 + 关键难点</li><li>【正文-成果】600字：规划输出 + 问题与调整</li><li>【正文-总结】400字：经验教训 + 持续改进 + 展望</li></ul><h3 id="论文选题方向" tabindex="-1">论文选题方向 <a class="header-anchor" href="#论文选题方向" aria-label="Permalink to &quot;论文选题方向&quot;">​</a></h3><table tabindex="0"><thead><tr><th>可能方向</th><th>核心章节</th><th>关键素材</th></tr></thead><tbody><tr><td>论信息系统规划方法</td><td>4.4</td><td>SST/BSP/CSF/VCA/Zachman选择理由+实施细节</td></tr><tr><td>论信息系统规划工作要点</td><td>4.3</td><td>五步法的完整实施过程</td></tr><tr><td>论信息系统发展战略</td><td>4.2.1</td><td>战略目标树+发展路径+五级成熟度</td></tr><tr><td>论信息系统系统框架设计</td><td>4.2.2</td><td>三种框架对比+选择理由</td></tr></tbody></table><hr><h2 id="🧠-六、核心记忆口诀" tabindex="-1">🧠 六、核心记忆口诀 <a class="header-anchor" href="#🧠-六、核心记忆口诀" aria-label="Permalink to &quot;🧠 六、核心记忆口诀&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内容</th><th>口诀</th><th>展开</th></tr></thead><tbody><tr><td>六大原则</td><td><strong>战整先指柔遵</strong></td><td>战略性、整体性、先进性、指导性、柔性、遵从性</td></tr><tr><td>五大成熟度</td><td><strong>一基二效三协四决五生态</strong></td><td>打基础→提效率→做协同→强决策→构生态</td></tr><tr><td>三种框架</td><td><strong>小应用、中平台、大互联</strong></td><td>应用功能主线→平台能力主线→互联网主线</td></tr><tr><td>技术六原则</td><td><strong>可用安全靠灵扩驾</strong></td><td>可用性、安全性、可靠性、灵活性、可扩展性、可驾驭性</td></tr><tr><td>五步要点</td><td><strong>需场诊规改</strong></td><td>需求挖掘→场景化分析→诊断评估→规划→持续改进</td></tr><tr><td>五方法</td><td><strong>S转B查C抓V链Z架</strong></td><td>SST战略转移、BSP企业调查、CSF关键成功、VCA价值链、Zachman框架</td></tr><tr><td>BSP四步骤</td><td><strong>目功数构</strong></td><td>目标→功能→数据类→信息结构</td></tr><tr><td>CSF四来源</td><td><strong>产竞环暂</strong></td><td>产业结构、竞争策略、环境因素、暂时因素</td></tr><tr><td>保障六体系</td><td><strong>组人技资数安</strong></td><td>组织、人员、技术、资源、数据、安全</td></tr></tbody></table><hr><h2 id="⚡-七、首考真题印证与易错点" tabindex="-1">⚡ 七、首考真题印证与易错点 <a class="header-anchor" href="#⚡-七、首考真题印证与易错点" aria-label="Permalink to &quot;⚡ 七、首考真题印证与易错点&quot;">​</a></h2><h3 id="首考已验证" tabindex="-1">首考已验证 <a class="header-anchor" href="#首考已验证" aria-label="Permalink to &quot;首考已验证&quot;">​</a></h3><ul><li>2025年11月综合真题：GBT43439（数字化转型成熟度）→ 4.3.3</li><li>五种规划方法首考尚未大规模覆盖，2026年概率极大</li></ul><h3 id="易混淆点" tabindex="-1">易混淆点 <a class="header-anchor" href="#易混淆点" aria-label="Permalink to &quot;易混淆点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>易混淆</th><th>区分</th></tr></thead><tbody><tr><td>BSP vs CSF</td><td>BSP全面调查（自顶向下），CSF抓住主要矛盾（少数关键）</td></tr><tr><td>VCA价值增加 vs 减少</td><td>增加=对客户贡献率，减少=降低满意度的影响</td></tr><tr><td>成熟度一级 vs 二级</td><td>一级=确立主要工作+基本策划，二级=管理精细化流程化</td></tr><tr><td>整体规划 vs 专项规划</td><td>整体=战略对齐+协同+资源配置；专项=领域详细设计+时间轴</td></tr></tbody></table><hr><blockquote><p>📅 更新时间：2026-05-25</p></blockquote>',108)])])}const b=d(o,[["render",n]]);export{m as __pageData,b as default};
